export default class MultiSelectable {
	constructor() {
		this.items = [];
	}

	get selected(){
		return this.items;
	}

	isSelected(val) {
		const currIdx = this.items.indexOf(val);
		return currIdx !== -1;
	}

	select(val) {
		const currIdx = this.items.indexOf(val);
		if (currIdx !== -1) {
			this.items.splice(currIdx, 1);
		} else {
			this.items.push(val);
		}
	}

	dropSelect() {
		this.items = [];
	}
}


