"use strict";


class EditEducCertifController {
    constructor($uibModalInstance, certifRepository, certifInfo, searchCtx, $controller, $scope, $http, $alerts, $appLoader, $dialogs, changeTracker) {

		this.certif = certifInfo;
		this.searchCtx = searchCtx;
		this.certifRepository = certifRepository;
		this.$uibModalInstance = $uibModalInstance;
		this.existingCertifStatus = certifInfo && certifInfo.id ? certifInfo.status : null;
		this.funcType = appContext.funcType;
		this.title = (certifInfo && certifInfo.id ? "Редактирование сертификата" : "Создание сертификата");
		this.student = null;
		this.endDateStr = dateUtils.date2str(moment(certifInfo.endDate).toDate());
		this.searchStudentMode = !this.certif.studentId || !this.certif.studentFio;
		this.editMode = this.certif.id > 0;
		this.createMode = !this.certif.id;
		this.$alerts = $alerts;
		this.addCertifCategories = [];
		this.certifRepository.getAddCertifCategories(this.certif.studentId).then((result) => {
			this.addCertifCategories = result;
		});
		$controller("NetCityModalController", { $scope, $dialogs, $uibModalInstance, changeTracker });
	}


	//рассчитать возраст студента
	calculateAge(birthDateStr) {

		let birthday = new Date(birthDateStr);

		let ageDifMs = Date.now() - birthday.getTime();
		let ageDate = new Date(ageDifMs); // miliseconds 
		let res = Math.abs(ageDate.getUTCFullYear() - 1970);
		return res;
	}

	//обработка события изменения статуса сертификата
	changeStatusHandler() {
		var studentBirthDate = this.certif.studentBirthDate;

		if (this.certif.status == "Actual") {
			if (this.calculateAge(studentBirthDate) >= 18) {
				$.show.error("Невозможно сделать актуальным сертификат для учащегося, достигшего возраста 18 лет");
				this.certif.status = "Frozen";
			}
		}

	}

	cancel() {
		this.$uibModalInstance.dismiss("cancel");
	}

	studentSelect(st) {
		if (!st || !st.birthDate) {
			return;
		}
		this.certif.studentId = st.id;
		this.certif.studentBirthDate = st.birthDate;
		this.certif.endDate = moment(st.birthDate).add(18, "years").startOf("day").toDate();
		this.endDateStr = dateUtils.date2str(moment(this.certif.endDate).toDate());
		this.certifRepository.getAddCertifCategories(this.certif.studentId).then((result) => {
			this.addCertifCategories = result;
			this.$scope.$apply();
		});
	}

	set() {
		const valid = this.educCertifForm.$valid && this.certif.startDate && this.endDateStr;
		if (!valid) {
			return;
		}

		const maxBirthDate = moment(this.certif.startDate).add(-5, "years").startOf("day").toDate();
		const minBirthDate = moment(this.certif.startDate).add(-18, "years").startOf("day").toDate();
		const isValidBirthDate = this.certif.studentBirthDate && moment(this.certif.studentBirthDate) > moment(minBirthDate) && moment(this.certif.studentBirthDate) <= moment(maxBirthDate);

		if (!isValidBirthDate) {
			alert("Сертификат дополнительного образования можно создать только для учащегося в возрасте от 5 до 18 лет");
			return;
		}

		this.certif.endDate = moment.utc(dateUtils.str2date(this.endDateStr)).toDate();

		if (this.editMode) {
			this.certifRepository.edit(this.certif).then(() => {
				this.$uibModalInstance.close(this.certif);
			});
		} else {
			this.certifRepository.create(this.certif).then(() => {
				this.$uibModalInstance.close(this.certif);
			});
		}
	}
}

module.exports = { EditEducCertifController };


