"use strict";

require("approot/global/controllers/registryCtrl.js");

import SearchSource from "approot/global/searchSource.js";
import { PfdoIntegrationType } from "approot/global/settingsProvider";

angular
	.module("irtech.netcity.school.educcertificates")
	.controller("IssuedEducCertifsCtrl", ($scope, $controller, $http, $document, $location, $appLoader, $uibModal, $alerts, $dialogs, certifRepository, downloadService, settingsProvider) => {

		$scope.$parent.page = {
			title: "Сертификаты дополнительного образования"
		};

		$scope.searchCtx = new SearchSource({
			students: {
				url: () => "/webapi/users/search",
				searchParam: "name",
				minChars: 1,
				map: (dto) => {
					dto.searchName = dto.name + " <i>(" + dateUtils.date2str(new Date(dto.birthDate)) + ")</i>";
					return dto;
				},
				params: {
					schoolId: appContext.schoolId,
					schoolYearId: appContext.yearId,
					withBirthDate: true,
					studentEnrollStatus: "Enrolled",
					student: true,
					take: 50,
					withoutActiveEducCertif: true,
					contains: true
				}
			}
		}, $http);

		const startDate = new Date();
		const endDate = moment(startDate).add(5, "years").startOf("day").toDate();

		$scope.emptyCertif = {
			id: null,
			number: null,
			startDate: startDate,
			endDate: endDate,
			status: "Actual",
			studentId: null,
			fio: null,
			schoolId: appContext.schoolId
		}

		$scope.add = () => {
			$scope.certifInfo = angular.copy($scope.emptyCertif);

			var modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/educcertificates/common/editEducCertificateTemplate.html",
				controller: 'EditCertifCtrl as editCtrl',
				resolve: {
					certifInfo: () => $scope.certifInfo,
					searchCtx: () => $scope.searchCtx
				}
			});

			modalInstance.rendered.then(() => {
				dateInput.initDateInputs(null, null, null, { format: dateUtils.getDateFormat().format });
			});

			modalInstance.result.then(() => {
				$scope.load();
			});
		}

		const dateDecorator = { type: "map", map: (date) => dateUtils.date2str(new Date(date)) };

		settingsProvider.ServerSettings.SystemSettings.IntegrationPFDOType().then((pfdoType) => {
			$scope.registry = {
				url: "/webapi/educcertificates/registry",
				filtersUrl: "/webapi/educcertificates/registry/filter",
				fieldDecorators: {
					"studentBirthDate": dateDecorator,
					"startDate": dateDecorator,
					"endDate": dateDecorator,
					"identityDocumentInfo": { type: "preserveWhiteSpace" },
					"parentsInfo": { type: "preserveWhiteSpace" },
					"addressInfo": { type: "preserveWhiteSpace" }
				},
				buttons: [
					{
						title: language.Generic.Buttons.kAdd,
						icon: "glyphicon glyphicon-plus-sign",
						action: () => {
							$scope.add();
						}
					}
				],
				linkButtons: []
			};

			if (pfdoType == PfdoIntegrationType.Volgograd) {
				$scope.registry.linkButtons.push({
					title: "Шаблон заявления",
					action: () => downloadService.downloadFile("/files/Шаблон Заявления.pdf", { filename: "Шаблон Заявления.pdf" })
				});
			}

			$controller("RegistryCommonCtrl", { $scope, $http, $document, $location, $appLoader, $uibModal, $alerts });
			
		});

	});



