"use strict";

import { BaseRepository } from "approot/global/repository.js";

class EducCertifRepository extends BaseRepository {
	create(certif) {
		return this.$http.post("/webapi/educcertificates", certif)
			.then((response) => {
				this.$alerts.success("Сертификат успешно добавлен");
				return response.data;
			})
			.catch(this.handleError);
	}

	edit(certif) {

		//этот кастомный обработчик ошибок нужен лишь для того чтобы привести к единому виду предупреждение об ошибке.
		let handleError = (response) => {
			let errText = '';
			if (response.data.details) {
				errText = response.data.details;
			} else if (response.data.message) {
				errText = response.data.message;
			}

			$.show.error(errText);
			return Promise.reject(response);
		}

		return this.$http.put("/webapi/educcertificates", certif)
			.then((response) => {
				this.$alerts.success("Сертификат успешно отредактирован");
				return response.data;
			})
			.catch(handleError);
	}

	remove(id) {
		return this.$http.delete(`/webapi/educcertificates/${id}`)
			.then(() => { this.$alerts.success("Сертификат успешно удален"); })
			.catch(this.handleError);
	}

	get(id) {
		return this.$http.get(`/webapi/educcertificates/${id}`)
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

	searchCertificate(searchData) {
		return this.$http.get("/webapi/educcertificates/searchCertif", { params: searchData })
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

	getAddCertifCategories(studentId) {
		return this.$http.get("/webapi/educcertificates/addcertifcategories", { params: { studentId: studentId}})
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

    //для текущей УО получить список дочерних УО включая саму текущую УО
    getChildEmWithMain() {
        return this.$http.get("/webapi/em/childs")
            .then((response) => {
                return response.data;
            })
            .catch(this.handleError);
    }

    updateMunicipalitetForCertif(certificate) {
        return this.$http.post("/webapi/educcertificates/updateMunicipalitets", certificate)
            .then((response) => {
                return response.data;
            })
            .catch(this.handleError);
    }
}

module.exports = { EducCertifRepository };


